import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:19.5px;line-height:1.25}.box h2{font-size:23px;margin-bottom:4px}.tbl{font-size:17.5px}.note,.warn{font-size:17px}.tbl th,.tbl td{padding:2px 6px}.iq ol{font-size:19px;line-height:1.26}.pill{font-size:16px}.grid{gap:10px}.handle{bottom:-12px}.box{padding:9px 12px}.tagline{font-size:19px;margin-bottom:9px}.code{font-family:Consolas,'DejaVu Sans Mono',monospace;background:#f1f5f9;border:1px dashed #94a3b8;border-radius:6px;padding:5px 7px;margin:4px 0;line-height:1.3;font-size:15.5px}</style>
<div class="title">📊 HxGN EAM Equipment Rankings <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Stop ranking criticality by gut feel: a survey + formulas turn answers into a score and an index on a schedule. (HxGN EAM 12.2 brief)</div>
<div class="grid">
<div class="box c1"><h2>1. Five ranking types (RATP)</h2><ul><li><b>Reliability Index</b> (also for Objectives)</li><li><b>Condition Index</b></li><li><b>Facility Condition Index</b></li><li><b>Risk Priority Index</b></li><li><b>Criticality Index</b></li></ul><div class="note">One asset can carry many rankings, e.g. a safety rank and an environment rank.</div></div>
<div class="box c2"><h2>2. Survey Setup tab (tree)</h2><ul><li>Branches go max <b>3 levels below the top</b></li><li>Lowest level of each branch = <b>question level</b></li><li>Answers: multiple choice (each has a Value) or Numeric / Integer with Min/Max</li><li>Non-question levels get a <b>formula</b></li><li><b>Normalize Level</b> when branches use different units</li></ul></div>
<div class="box c3"><h2>3. Three ways to answer</h2><table class="tbl"><tr><th>Source</th><th>How</th></tr><tr><td>Manual</td><td>Ranking Survey tab</td></tr><tr><td>Calculated</td><td>Query Code from the Queries screen</td></tr><tr><td>Checklist</td><td>Aspect + Checklist Type; latest result on a <b>completed</b> WO</td></tr></table></div>
<div class="box c4"><h2>4. Calculated question query</h2><div class="code">SELECT number FROM table<br>WHERE equipment = :OBJECT<br>AND organization = :OBJECTORG</div><ul><li>Must return <b>1 row, 1 column</b></li><li>Tick Query Option "Equipment Ranking"</li><li>:RANKINGLEVEL, :FROMPOINT, :TOPOINT also available</li></ul></div>
<div class="box c5"><h2>5. Formula roll-up</h2><div class="code">L1.1 = :L2.1 * 2 + 10<br>TOP = GREATEST(:L1.1, :L1.2 * 2)<br>  + ROUND(:L1.1 * 10 / :L1.2, 1)</div><div class="warn">A NULL query result makes the formula fail: wrap with COALESCE(:param, 0). A missing checklist result has no such fix.</div></div>
<div class="box c6"><h2>6. Ranks tab: score → index</h2><ul><li>Min / Max Value → <b>Ranking Index</b> (entity OBRI)</li><li>Criticality Index type uses <b>OBCR</b></li><li>Color + Icon drive the Linear Overview</li><li>No Ranks for Facility Condition Index</li><li><b>Track History</b>: condition, risk priority, criticality only</li></ul></div>
<div class="box c7"><h2>7. Condition protocols</h2><ul><li>Condition Inspection (survey based)</li><li>Age, Usage</li><li>Decay Curve (Age / % of Age / Usage / % of Usage)</li><li>Score Start, End and Threshold = end of useful life</li></ul><div class="code">20-yr life, score 1→5, year 10:<br>1 + (5-1)/20*10 = 3<br>Correction to 2 → year 11 = 2.2</div></div>
<div class="box c8"><h2>8. Rankings tab on the asset</h2><ul><li>Unlimited Reliability Indexes; only <b>one</b> Condition Index and one Facility Condition Index</li><li><b>Default</b> one Reliability ranking shows on Record View</li><li><b>Lock Ranking Values</b> stops recalculation</li><li>Out of Sync flag when setup changed later</li><li>A calculated Criticality <b>overwrites</b> a manual one</li></ul></div>
<div class="box c1" style="grid-column:1 / span 2"><h2>9. Recalculation + bulk</h2><table class="tbl"><tr><th>Feature</th><th>What it does</th></tr><tr><td><b>CALCRANK</b> batch job</td><td>Activate on Job Setup. Picks unlocked records where Next Refresh ≤ today (or Refresh Every set, Next Refresh blank); sets Ranking Calculation Error and continues on failure</td></tr><tr><td><b>Refresh Sequence</b></td><td>Children = 1, parent = 2 when the parent score depends on children (blanks run first)</td></tr><tr><td><b>Batch Update Equipment Ranking Values</b></td><td>Pick by class / category / equipment + Include Children; Apply, Detach or Set as Default; calculate here only if no calculated or checklist questions</td></tr><tr><td><b>Objectives / Strategies / Policies</b></td><td>One ranking each, type Reliability Index; no checklist questions</td></tr></table></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">10a. Setup flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Queries + Decay Curves</span><span class="arr">→</span><span class="pill">Equipment Ranking + Type</span><span class="arr">→</span><span class="pill">Survey tree + formulas</span><span class="arr">→</span><span class="pill">Ranks tab</span><span class="arr">→</span><span class="pill">Attach to assets (batch)</span><span class="arr">→</span><span class="pill">CALCRANK</span></div></div>
<div class="box iq"><h2>10b. Consultant tips</h2><ol><li>Test each query returns 1 value</li><li>COALESCE every calculated param</li><li>Use Refresh Sequence for parent/child</li><li>Small batches beat one big batch</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">10c. Key points</h2><ul><li>Same logic, same rank, every time</li><li>Scores refresh as data changes</li><li>Feeds RCM, risk and capital plans</li></ul></div>
</div></div>'''
build("/workspace/instagram-assets/posts/2026-10-28-linkedin-eam-equipment-rankings",B,1620,"Rahul Kumar")
